// Windowless test for julia_lsp.cpp -- the analysis half of mep's own
// Julia language server (`mep-julia-lsp`). Drives the pure functions
// directly: no process, no JSON-RPC client. CHECK(), never assert(): the
// Release build strips assert(). Generated by tools/new_language.py.
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>

#include "julia_lsp.h"

#include <unistd.h>

namespace {
int g_checks = 0;

void Check(bool ok, const char *expr, int line) {
    g_checks++;
    if (ok) return;
    std::fprintf(stderr, "CHECK FAILED: %s at %s:%d\n", expr, __FILE__, line);
    std::abort();
}
#define CHECK(c) Check((c), #c, __LINE__)

std::vector<std::string> L(const std::string &text) {
    std::vector<std::string> out;
    std::string cur;
    for (char c : text) {
        if (c == '\n') {
            out.push_back(cur);
            cur.clear();
        } else {
            cur += c;
        }
    }
    out.push_back(cur);
    return out;
}

bool HasCode(const std::vector<JuliaLspDiagnostic> &ds, const std::string &code) {
    for (const auto &d : ds)
        if (d.code == code) return true;
    return false;
}

const JuliaLspDiagnostic *Find(const std::vector<JuliaLspDiagnostic> &ds, const std::string &code) {
    for (const auto &d : ds)
        if (d.code == code) return &d;
    return nullptr;
}

std::vector<JuliaLspDiagnostic> Diags(const std::string &src) { return JuliaLspDiagnostics(*JuliaLspAnalyze(L(src))); }

void TestSyntax() {
    // JuliaSyntax's own message and position.
    const auto ds = Diags("x = (1 +\nf(a b)\n");
    const auto *d = Find(ds, "syntax-error");
    CHECK(d != nullptr);
    CHECK(d->message == "Expected `)` or `,`");
    CHECK(d->range.line == 1);
    CHECK(JuliaLspJuliaCheck("x = (1 +\nf(a b)\n") == "2:4: Expected `)` or `,`");
    CHECK(JuliaLspJuliaCheck("function f(x)\n  x+1\nend\n").empty());
    CHECK(Diags("function f(x)\n    x + 1\nend\n").empty());
}

void TestLowering() {
    const auto dup = Diags("f(x, x) = 1\n");
    const auto *d = Find(dup, "duplicate-argument");
    CHECK(d != nullptr);
    CHECK(d->message == "function argument name not unique: \"x\"");
    CHECK(HasCode(Diags("function g(a; a=1) end\n"), "duplicate-argument"));
    CHECK(HasCode(Diags("break\n"), "break-outside-loop"));
    CHECK(!HasCode(Diags("for i in 1:2\n    i > 1 && break\nend\n"), "break-outside-loop"));
    CHECK(HasCode(Diags("struct S\n    a\n    a::Int\nend\n"), "duplicate-field"));
    CHECK(HasCode(Diags("f(a=1, a=2)\n"), "duplicate-keyword-argument"));
    CHECK(HasCode(Diags("function m()\n    const y = 1\n    y\nend\n"), "local-const"));
    CHECK(HasCode(Diags("function q(x)\n    local x = 1\n    x\nend\n"), "local-argument-conflict"));
    CHECK(HasCode(Diags("let\n    local x\n    global x\nend\n"), "local-global-conflict"));
}

void TestLints() {
    const auto ds = Diags("function f(x, y)\n    z = 1\n    w = x\n    return w\nend\n");
    const auto *u = Find(ds, "unused-local");
    CHECK(u != nullptr && u->range.line == 1);
    const auto *a = Find(ds, "unused-argument");
    CHECK(a != nullptr && a->message.find("`y`") != std::string::npos);
    // Loops and closures update an enclosing local: no unused report.
    CHECK(!HasCode(Diags("function f()\n    s = 0\n    for i in 1:3\n        s += i\n    end\n    s\nend\n"),
                   "unused-local"));
    CHECK(!HasCode(Diags("function f()\n    n = 0\n    g = () -> (n += 1)\n    g()\n    n\nend\n"), "unused-local"));
    CHECK(HasCode(Diags("h(x) where {T} = x\n"), "unused-type-parameter"));
    CHECK(!HasCode(Diags("h(x::T) where {T} = x\n"), "unused-type-parameter"));
    CHECK(HasCode(Diags("x = 1\nx == nothing\n"), "compare-nothing"));
    CHECK(HasCode(Diags("function f()\n    return 1\n    2\nend\n"), "unreachable"));
    // A near miss of a local is reported; an unknown name with no near miss is not.
    const auto nm = Diags("module M\nfunction f()\n    length_total = 3\n    length_totl + 1\nend\nend\n");
    const auto *n = Find(nm, "undefined-name");
    CHECK(n != nullptr && n->message.find("length_total") != std::string::npos);
    CHECK(!HasCode(Diags("function f()\n    some_package_function(1)\nend\n"), "undefined-name"));
    // A file's top level may be include()d: its names are never knowable.
    CHECK(!HasCode(Diags("function f()\n    length_total = 3\n    length_totl + 1\nend\n"), "undefined-name"));
    // Dispatch-only and catch-all arguments, string-macro interpolation, named tuples.
    CHECK(!HasCode(Diags("f(x::Int; kw...) = 1\n"), "unused-argument"));
    CHECK(!HasCode(Diags("function f(p)\n    link = p\n    styled\"{link=$link}\"\nend\n"), "unused-local"));
    CHECK(!HasCode(Diags("f(x) = (read = x, write = false)\n"), "unused-local"));
    CHECK(!HasCode(Diags("function f(p)\n    exe = p\n    run(`$exe -e 1`)\nend\n"), "unused-local"));
    CHECK(!HasCode(Diags("module M\nconst A{T} = Union{Vector{T}, Set{T}}\nf(::A) = 1\nend\n"), "undefined-name"));
    CHECK(!HasCode(Diags("h(s::S{T}) where {T} = s\n"), "unused-type-parameter"));
    CHECK(!HasCode(Diags("h(a::A) where {T, A<:AbstractVector{T}} = a\n"), "unused-type-parameter"));
    CHECK(!HasCode(Diags("x = 1\n@testset for i in 1:2\n    x = i\nend\n"), "soft-scope"));
    // Soft scope at the top level.
    CHECK(HasCode(Diags("s = 0\nfor i in 1:3\n    s = i\nend\n"), "soft-scope"));
    CHECK(!HasCode(Diags("s = 0\nfor i in 1:3\n    global s = i\nend\n"), "soft-scope"));
}

void TestNavigation() {
    const auto doc = JuliaLspAnalyze(L("function f(x)\n    y = x + 1\n    y * 2\nend\nf(3)\n"));
    const auto defs = JuliaLspDefinition(*doc, 2, 4);  // y
    CHECK(defs.size() == 1 && defs[0].range.line == 1 && defs[0].range.col == 4);
    const auto refs = JuliaLspReferences(*doc, 1, 4);
    CHECK(refs.size() == 2);
    std::string err;
    const auto edits = JuliaLspRename(*doc, 0, 11, "arg", &err);  // x
    CHECK(edits.size() == 2);
    CHECK(JuliaLspRename(*doc, 0, 11, "y", &err).empty() && !err.empty());  // captured by y
    const auto fdefs = JuliaLspDefinition(*doc, 4, 0);
    CHECK(fdefs.size() == 1 && fdefs[0].range.line == 0);
}

void TestHoverCompletion() {
    const auto doc = JuliaLspAnalyze(L("\"\"\"\n    twice(x)\n\nDoubles.\n\"\"\"\ntwice(x) = 2x\ntwice(1)\nsum([1])\n"
                                       "using LinearAlgebra\nnorm\nfo"));
    const auto h = JuliaLspHover(*doc, 6, 1);
    CHECK(h.found && h.text.find("Doubles.") != std::string::npos);
    const auto hs = JuliaLspHover(*doc, 7, 1);
    CHECK(hs.found && hs.text.find("Base") != std::string::npos);
    const auto hn = JuliaLspHover(*doc, 9, 1);
    CHECK(hn.found && hn.text.find("LinearAlgebra") != std::string::npos);
    const auto items = JuliaLspCompletions(*doc, 10, 2);
    bool has_for = false, has_foldl = false;
    for (const auto &it : items) {
        has_for = has_for || it.label == "for";
        has_foldl = has_foldl || it.label == "foldl";
    }
    CHECK(has_for && has_foldl);
    const auto sh = JuliaLspSignatureAt(*JuliaLspAnalyze(L("twice(x) = 2x\ntwice(")), 1, 6);
    CHECK(sh.found && sh.label == "twice(x)");
}

void TestOutline() {
    const auto doc = JuliaLspAnalyze(L("module M\nstruct P\n    x::Int\nend\nf(p::P) = p.x\nmacro m(e)\n    e\nend\n"
                                       "const K = 1\nend\n"));
    const auto syms = JuliaLspSymbols(*doc);
    CHECK(syms.size() == 6);  // M, P, x, f, @m, K
    CHECK(syms[0].name == "M" && syms[1].name == "P" && syms[2].name == "x" && syms[2].parent == 1);
    CHECK(syms[4].name == "@m");
    const auto folds = JuliaLspFolds(*doc);
    CHECK(!folds.empty() && folds[0].start_line == 0);
}

void TestRobustness() {
    // Every query on every prefix of a file must not crash.
    const std::string src =
        "module M\nusing Base: @kwdef\n\"\"\"doc\"\"\"\nfunction f(x::T, y=1; k...) where {T<:Real}\n"
        "    z = [i^2 for i in 1:x if isodd(i)]\n    s = \"a$(x)b\"\n    try\n        g(x) do a\n            a + 1\n"
        "        end\n    catch e\n        rethrow()\n    end\n    return z, s\nend\n@kwdef struct S{T}\n    a::T = 1\nend\n"
        "x -> x'\nq = :(a + $b)\nend\n";
    for (size_t n = 0; n <= src.size(); n++) {
        const auto lines = L(src.substr(0, n));
        const auto doc = JuliaLspAnalyze(lines);
        const int last = static_cast<int>(lines.size()) - 1;
        const int col = static_cast<int>(lines.back().size());
        JuliaLspDiagnostics(*doc);
        JuliaLspCompletions(*doc, last, col);
        JuliaLspHover(*doc, last, col);
        JuliaLspSignatureAt(*doc, last, col);
        JuliaLspDefinition(*doc, last, col);
        JuliaLspReferences(*doc, last, col);
        JuliaLspSymbols(*doc);
        JuliaLspFolds(*doc);
    }
}


bool Has(const std::string &text, const std::string &part) { return text.find(part) != std::string::npos; }

// `using Pkg`: a package on the load path (here the shape of a Rosetta-generated module) lends
// its exports, docstrings and definition sites to hover, completion, signatures and navigation.
void TestPackages() {
    namespace fs = std::filesystem;
    const fs::path root = fs::temp_directory_path() / ("mep-julia-lsp-test-" + std::to_string(::getpid()));
    fs::create_directories(root / "Shapes" / "src");
    const std::string source =
        "\"\"\"\n    Shapes\n\nNative shapes.\n\"\"\"\n"
        "module Shapes\n"
        "module _Rosetta\nabstract type NativeObject end\nend\n"
        "using ._Rosetta: NativeObject\n"
        "export NativeObject, Shape, Circle, area, golden\n"
        "\"\"\"\n    Shape <: NativeObject\n\nA shape.\n\"\"\"\n"
        "abstract type Shape <: NativeObject end\n"
        "abstract type Circle <: Shape end\n"
        "\"\"\"\n    Circle(radius::Float64) -> Circle\n\nA circle of `radius`.\n\"\"\"\n"
        "Circle(radius) = nothing\n"
        "\"\"\"\n    area\n\nMethods for `Circle`.\n\"\"\"\n"
        "function area end\n"
        "\"\"\"\n    area(self::Circle) -> Float64\n\nThe area, in square units.\n\"\"\"\n"
        "area(self::Circle, args...) = 0.0\n"
        "\"\"\"\n    size(self::Circle) -> Int\n\nVertices.\n\"\"\"\n"
        "Base.size(self::Circle, args...) = 0\n"
        "\"\"\"\n    repeat(text::String, n::Int) -> String\n\nNot exported (Base has `repeat`).\n\"\"\"\n"
        "repeat(args...) = nothing\n"
        "\"\"\"\n    golden::Float64\n\nThe golden ratio.\n\"\"\"\n"
        "golden = nothing\n"
        "end # module Shapes\n";
    { std::ofstream(root / "Shapes" / "src" / "Shapes.jl") << source; }
    const std::vector<std::string> load_path{root.string()};
    JuliaLspSetLoadPath(&load_path);

    const auto doc = JuliaLspAnalyze(L("using Shapes\nc = Circle(2.0)\nx = area(c)\ny = size(c)\nShapes.repeat(\"a\", 2)\ngolden\nar"));
    // Exported names are known: no undefined-name diagnostics.
    for (const auto &d : JuliaLspDiagnostics(*doc)) CHECK(d.code != "undefined-name");
    // Hover: the package's docstrings.
    auto h = JuliaLspHover(*doc, 2, 5);
    CHECK(h.found && Has(h.text, "area(self::Circle) -> Float64") && Has(h.text, "The area, in square units.") &&
          Has(h.text, "in `Shapes`"));
    CHECK(Has(JuliaLspHover(*doc, 1, 5).text, "A circle of `radius`."));
    // A Base function extended for the package's types: its own docstring comes first.
    h = JuliaLspHover(*doc, 3, 5);
    CHECK(h.found && Has(h.text, "Vertices."));
    CHECK(Has(JuliaLspHover(*doc, 4, 8).text, "Not exported"));
    CHECK(Has(JuliaLspHover(*doc, 5, 2).text, "The golden ratio."));
    CHECK(Has(JuliaLspHover(*doc, 0, 8).text, "Native shapes."));
    // Completion: exported names (not unexported ones), and `Shapes.` lists everything.
    bool area = false;
    for (const auto &c : JuliaLspCompletions(*doc, 6, 2)) area = area || (c.label == "area" && Has(c.documentation, "square units"));
    CHECK(area);
    const auto qualified = JuliaLspAnalyze(L("using Shapes\nShapes.rep"));
    bool repeat = false;
    for (const auto &c : JuliaLspCompletions(*qualified, 1, 10)) repeat = repeat || c.label == "repeat";
    CHECK(repeat);
    // Signature help from the docstring's signature line.
    const auto call = JuliaLspAnalyze(L("using Shapes\narea("));
    const auto sh = JuliaLspSignatureAt(*call, 1, 5);
    CHECK(sh.found && Has(sh.label, "area(self::Circle)"));
    // Definitions jump into the package file.
    const auto defs = JuliaLspDefinition(*doc, 2, 5);
    CHECK(!defs.empty() && Has(defs.front().path, "Shapes.jl") && defs.front().range.line > 0);
    // Not found: unknown as before (no diagnostics about its names).
    const auto unknown = JuliaLspAnalyze(L("using NotThere\nfoo()"));
    for (const auto &d : JuliaLspDiagnostics(*unknown)) CHECK(d.code != "undefined-name");

    JuliaLspSetLoadPath(nullptr);
    fs::remove_all(root);
}

}  // namespace

int main() {
    TestSyntax();
    TestLowering();
    TestLints();
    TestNavigation();
    TestHoverCompletion();
    TestOutline();
    TestRobustness();
    TestPackages();
    std::printf("julia_lsp_test: %d checks passed\n", g_checks);
    return 0;
}
